const canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),stage=document.querySelector('.stage');
let mode=0,time=0,rx=.35,ry=.25,zoom=1,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,speed=.6,complexity=.7,color=[255,97,56],drag=null,last=0,w=1,h=1;
let pointer={x:0,y:0,inside:false},ripples=[],trail=[],lastTrail=0;
const works=[{name:'SILK / WIND',a:'Wind',b:'Weave',caption:'Sculpting the invisible',detail:'Pass through the threads to bend the wind.',hint:'Move to stir · Drag to orbit · Scroll to zoom'},{name:'IMPOSSIBLE WATER',a:'Flow',b:'Resonance',caption:'A surface that remembers',detail:'Touch anywhere to set a ripple in motion.',hint:'Touch to ripple · Drag to orbit · Scroll to zoom'},{name:'AFTERIMAGE',a:'Drift',b:'Memory',caption:'A sculpture of your presence',detail:'Draw in the dark. Watch your gestures become space.',hint:'Move or drag to draw · Arrow keys to orbit · Scroll to zoom'}];
function size(){let r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio,2);w=r.width;h=r.height;canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0)}new ResizeObserver(size).observe(canvas);
function project(x,y,z){let a=ry+time*.055,c=Math.cos(a),s=Math.sin(a),xx=x*c-z*s,zz=x*s+z*c,yy=y*Math.cos(rx)-zz*Math.sin(rx);zz=y*Math.sin(rx)+zz*Math.cos(rx);let scale=Math.min(w,h)*.29*zoom/(1+zz*.15);return [w/2+xx*scale,h/2+yy*scale]}
function ink(alpha,mix=0){return `rgba(${color.map(v=>Math.round(v+(255-v)*mix))},${alpha})`}
function path(points,stroke,width=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()}
function silk(){let count=Math.floor(50+complexity*85);ctx.globalCompositeOperation='screen';for(let j=0;j<count;j++){let v=j/count*Math.PI*2,pts=[];for(let i=0;i<=130;i++){let u=i/130*Math.PI*2,twist=v+u*2,r=1+.36*Math.cos(twist),x=r*Math.cos(u),z=r*Math.sin(u),y=.48*Math.sin(twist)+Math.sin(u*3+time*.65+v)*.1,force=pointer.inside?Math.exp(-((x-pointer.x*1.5)**2+(y-pointer.y)**2)*1.8):0;y+=force*.38*Math.sin(time*1.5+u*3);z+=force*pointer.x*.35;pts.push(project(x,y,z))}path(pts,ink(.16+Math.sin(v)*.05,(1+Math.sin(v))*.22),.65)}ctx.globalCompositeOperation='source-over'}
function height(x,z){let y=.06*Math.sin(x*4+time)*Math.cos(z*3+time*.6);for(let r of ripples){let age=time-r.t,dist=Math.hypot(x-r.x,z-r.z);y+=Math.sin(dist*9-age*5)*Math.exp(-Math.abs(dist-age*.6)*2.4)*Math.exp(-age*.55)*.22*(.5+complexity)}return y}
function water(){ctx.globalCompositeOperation='screen';let count=Math.floor(45+complexity*45);for(let j=0;j<count;j++){let z=(j/(count-1)-.5)*3.8,pts=[];for(let i=0;i<=110;i++){let x=(i/110-.5)*3.8;pts.push(project(x,height(x,z),z))}path(pts,ink(.22,.25+j/count*.45),.8)}for(let j=0;j<20;j++){let x=(j/19-.5)*3.8,pts=[];for(let i=0;i<=80;i++){let z=(i/80-.5)*3.8;pts.push(project(x,height(x,z),z))}path(pts,ink(.09,.5),.5)}ripples=ripples.filter(r=>time-r.t<10);ctx.globalCompositeOperation='source-over'}
function afterimage(){trail=trail.filter(p=>time-p.t<4+complexity*18);ctx.globalCompositeOperation='screen';let strands=9+Math.floor(complexity*15);for(let j=0;j<strands;j++){let pts=[],v=j/strands*Math.PI*2;for(let p of trail){let age=time-p.t,rad=.065+age*.025;pts.push(project(p.x+Math.cos(v+age*.8)*rad,p.y+Math.sin(v+age*.8)*rad,p.z-age*.025))}if(pts.length>1)path(pts,ink(.25,.15+j/strands*.6),.65)}for(let k=0;k<trail.length;k+=8){let p=trail[k],age=time-p.t,rad=.065+age*.025,pts=[];for(let j=0;j<=28;j++){let v=j/28*Math.PI*2;pts.push(project(p.x+Math.cos(v+age*.8)*rad,p.y+Math.sin(v+age*.8)*rad,p.z-age*.025))}path(pts,ink(.12,.5),.55)}ctx.globalCompositeOperation='source-over';if(!trail.length){ctx.fillStyle='#c4c8b8';ctx.textAlign='center';ctx.font='12px "DM Sans", sans-serif';ctx.fillText('Move here. Leave an afterimage.',w/2,h/2)}}
function render(now){let dt=Math.min((now-last)/1000,.04);last=now;if(!paused)time+=dt*speed;ctx.fillStyle=mode===1?'#172123':'#181d19';ctx.fillRect(0,0,w,h);let glow=ctx.createRadialGradient(w/2,h/2,0,w/2,h/2,Math.max(w,h)*.6);glow.addColorStop(0,mode===1?'#2e4a4828':'#6a553222');glow.addColorStop(1,'#00000000');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);if(mode===0)silk();else if(mode===1)water();else afterimage();requestAnimationFrame(render)}requestAnimationFrame(render);
function locate(e){let r=canvas.getBoundingClientRect();pointer.x=((e.clientX-r.left)/r.width-.5)*2;pointer.y=((e.clientY-r.top)/r.height-.5)*2;pointer.inside=true}
function remember(){if(paused)return;if(trail.length>900)trail.shift();trail.push({x:pointer.x*w/Math.min(w,h)*1.6/zoom,y:pointer.y*1.65/zoom,z:Math.sin(time*.7)*.55,t:time})}
function ripple(){if(paused)return;ripples.push({x:pointer.x*1.9,z:pointer.y*1.9,t:time});if(ripples.length>20)ripples.shift()}
const pause=document.getElementById('pause');function pauseUI(){pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',paused?'Resume animation':'Pause animation')}pauseUI();pause.onclick=()=>{paused=!paused;pauseUI()};
document.querySelectorAll('.experiment').forEach(b=>{b.setAttribute('aria-pressed',b.classList.contains('active'));b.onclick=()=>{mode=+b.dataset.mode;const work=works[mode];document.querySelectorAll('.experiment').forEach(e=>{e.classList.toggle('active',e===b);e.setAttribute('aria-pressed',String(e===b))});document.querySelector('#scene-title').textContent=`0${mode+1} / ${work.name}`;document.querySelector('#parameter-a').textContent=work.a;document.querySelector('#parameter-b').textContent=work.b;const caption=document.querySelector('#work-caption');caption.replaceChildren(document.createTextNode(work.caption),Object.assign(document.createElement('small'),{textContent:work.detail}));document.querySelector('.stage-bottom>span').textContent=work.hint;rx=mode===1?.8:.35;ry=.25;zoom=1;ripples=[];trail=[];if(mode===1)ripples.push({x:0,z:0,t:time})}});
for(let id of ['speed','complexity'])document.getElementById(id).oninput=e=>{let v=+e.target.value;if(id==='speed')speed=v;else complexity=v;document.getElementById(id+'-value').textContent=v.toFixed(2)};
document.querySelectorAll('.swatch').forEach(b=>{b.setAttribute('aria-pressed',b.classList.contains('selected'));b.onclick=()=>{color=b.dataset.color.split(',').map(Number);document.querySelectorAll('.swatch').forEach(e=>{e.classList.toggle('selected',e===b);e.setAttribute('aria-pressed',String(e===b))})}});
document.getElementById('reset').onclick=()=>{rx=mode===1?.8:.35;ry=.25;zoom=1;time=0;ripples=[];trail=[]};canvas.onpointerdown=e=>{locate(e);drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId);if(mode===1)ripple();if(mode===2)remember()};canvas.onpointermove=e=>{locate(e);if(drag&&mode!==2){ry+=(e.clientX-drag[0])*.008;rx+=(e.clientY-drag[1])*.008;drag=[e.clientX,e.clientY]}if(mode===2&&performance.now()-lastTrail>16){remember();lastTrail=performance.now()}};canvas.onpointerleave=()=>pointer.inside=false;canvas.onpointerup=canvas.onpointercancel=()=>drag=null;canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.4,Math.min(2.2,zoom-e.deltaY*.001))},{passive:false});canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','=',' '].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')ry-=.1;if(e.key==='ArrowRight')ry+=.1;if(e.key==='ArrowUp')rx-=.1;if(e.key==='ArrowDown')rx+=.1;if(e.key==='+'||e.key==='=')zoom=Math.min(2.2,zoom+.1);if(e.key==='-')zoom=Math.max(.4,zoom-.1);if(e.key===' '){pointer.x=0;pointer.y=0;if(mode===1)ripple();if(mode===2){pointer.x=Math.sin(time)*.5;remember()}}}};
document.getElementById('capture').onclick=()=>{canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`spatial-${['silk-wind','impossible-water','afterimage'][mode]}-${Date.now()}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})};
const fullscreen=document.getElementById('fullscreen');fullscreen.onclick=async()=>{if(document.fullscreenElement){await document.exitFullscreen();return}if(stage.requestFullscreen){try{await stage.requestFullscreen();return}catch{}}stage.classList.toggle('immersive');fullscreen.textContent=stage.classList.contains('immersive')?'×':'⤢'};document.addEventListener('keydown',e=>{if(e.key==='Escape'){stage.classList.remove('immersive');fullscreen.textContent='⤢'}});const exit=document.createElement('button');exit.className='exit-immersive';exit.textContent='Exit immersive view ↙';exit.onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();stage.classList.remove('immersive');fullscreen.textContent='⤢'};stage.append(exit);
document.getElementById('about').onclick=()=>document.querySelector('dialog').showModal();document.getElementById('close').onclick=()=>document.querySelector('dialog').close();canvas.setAttribute('aria-label','Interactive browser artwork. Drag or use arrow keys to rotate. Move to disturb silk or draw an afterimage. Click or press space to create a water ripple.');
